var graph5 = ee.Algorithms.If(
  precocearenizacao.isValid() && precocearenizacao.bandNames().size().gt(0),
  ui.Chart.image.histogram(
    precocearenizacao, 
    geomTeste,  // Usar geometria de teste
    30, 
