var graph6 = ee.Algorithms.If(
  tardioarenizacao.isValid() && tardioarenizacao.bandNames().size().gt(0),
  ui.Chart.image.histogram(
    tardioarenizacao, 
    geomTeste,  // Usar geometria de teste
